class Customer:
    def __init__(self, id: CustomerId, name: str) -> None:
        self.id = id                  # identity: assigned once, never reassigned
        self.name = name              # state may change

    def rename(self, name: str) -> None:
        self.name = name

    def __eq__(self, other: object) -> bool:
        return isinstance(other, Customer) and other.id == self.id

    def __hash__(self) -> int:
        return hash(self.id)          # must agree with __eq__
